PYTHONPATH=src python - <<'EOF'
import itertools, random
from swarmgrid.model import Map, Mission, parse_closures
from swarmgrid.solver import plan_mission, detect_conflicts, position_at

H = 8

def closure_ok(paths, closures):
    for path in paths:
        for t, cell in enumerate(path):
            for c in closures:
                if c.start_tick <= t <= c.end_tick and cell in c.cells_set:
                    return False
    return True

def brute(map_rec, agents, closures, horizon=H):
    all_paths = []
    for agent in agents:
        single = []
        stack = [(agent.start, (agent.start,))]
        while stack:
            cell, path = stack.pop()
            if len(path) - 1 > horizon:
                continue
            if any(c.start_tick <= len(path)-1 <= c.end_tick and cell in c.cells_set for c in closures):
                continue
            if cell == agent.goal:
                single.append(path); continue
            for nb in map_rec.neighbors(cell):
                if any(c.start_tick <= len(path) <= c.end_tick and nb in c.cells_set for c in closures):
                    continue
                stack.append((nb, path + (nb,)))
            stack.append((cell, path + (cell,)))
        all_paths.append(single)
    for combo in itertools.product(*all_paths):
        if not detect_conflicts(tuple(agents), list(combo)):
            return list(combo)
    return None

rng = random.Random(20260930)
solved = unsolvable = false_neg = 0
trials = 0
while trials < 400:
    w = rng.randint(2, 4); h = rng.randint(2, 4)
    rows = ["".join("#" if rng.random() < 0.25 else "." for _ in range(w)) for _ in range(h)]
    free = [(x,y) for y in range(h) for x in range(w) if rows[y][x]=="."]
    if len(free) < 3: continue
    map_rec = Map.parse({"id":"m","width":w,"height":h,"grid":rows})
    n = rng.randint(1, min(2, len(free)-1))
    starts = rng.sample(free, n)
    goals = []
    for s in starts:
        pool = [c for c in free if c != s and c not in goals]
        goals.append(rng.choice(pool))
    agents = [{"id":f"a{i}","start":list(s),"goal":list(g)} for i,(s,g) in enumerate(zip(starts,goals))]
    try:
        mission = Mission.parse({"id":"x","map_id":"m","agents":agents}, map_rec)
    except Exception:
        continue
    raw = []
    for _ in range(rng.randint(1,3)):
        cells = [list(c) for c in rng.sample(free, rng.randint(1,min(3,len(free))))]
        a = rng.randint(0,H); b = rng.randint(a,H)
        raw.append({"cells":cells,"start_tick":a,"end_tick":b})
    closures = parse_closures(raw, map_rec)
    r = plan_mission(map_rec, mission, closures=closures)
    trials += 1
    agents_sorted = tuple(sorted(mission.agents, key=lambda a:a.id))
    if r.status == "solved":
        assert not detect_conflicts(agents_sorted, list(r.paths)), "conflict!"
        assert closure_ok(r.paths, closures), "closure violated!"
        solved += 1
    else:
        unsolvable += 1
        witness = brute(map_rec, agents_sorted, closures)
        if witness is not None:
            wider = plan_mission(map_rec, mission, order_budget=5040, tree_budget=4096, closures=closures)
            if wider.status != "solved":
                false_neg += 1
                print("FALSE NEG", rows, agents, raw, witness)
print(f"trials={trials} solved={solved} unsolvable={unsolvable} false_negatives={false_neg}")
EOF

